                            <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => setIsCreating(true)}
                                className="text-muted-foreground hover:text-foreground"
                                aria-label="Create playlist"
                            >
                                <Plus className="h-5 w-5" />
                            </Button>
                            <Button
                                variant="ghost"
                                size="icon"
                                onClick={onClose}
                                className="text-muted-foreground hover:text-foreground @lg:hidden"
                                aria-label="Close sidebar"
                            >
                                <X className="h-5 w-5" />
                            </Button>
                        </div>
                    </div>

                    {/* Create playlist form */}
                    {isCreating && (
                        <div className="border-b border-border p-4">
                            <Input
                                type="text"
                                placeholder="Playlist name..."
                                value={newPlaylistName}
                                onChange={(e) =>
                                    setNewPlaylistName(e.target.value)
                                }
                                onKeyDown={(e) =>
                                    e.key === \'Enter\' && handleCreatePlaylist()
                                }
                                className="mb-2"
                                autoFocus
                            />
                            <div className="flex gap-2">
                                <Button
                                    size="sm"
                                    onClick={handleCreatePlaylist}
                                    className="flex-1"
                                >
                                    Create
                                </Button>
                                <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() => {
                                        setIsCreating(false);
                                        setNewPlaylistName(\'\');
                                    }}
                                >
                                    Cancel
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* Playlist list */}
                    <div className="flex-1 overflow-y-auto">
                        {playlists.map((playlist) => (
                            <div
                                key={playlist.id}
                                className="border-b border-border/50"
                            >
                                <button
                                    onClick={() => {
                                        onSelectPlaylist(playlist);
                                        toggleExpand(playlist.id);
                                    }}
                                    className={cn(
                                        \'flex w-full items-center gap-3 p-4 transition-colors hover:bg-muted/50\',
                                        currentPlaylist?.id === playlist.id &&
                                            \'bg-muted\',
                                    )}
                                >
                                    <div className="relative h-12 w-12 flex-shrink-0 overflow-hidden rounded-lg bg-muted">
                                        {playlist.coverUrl ? (
                                            <img
                                                src={playlist.coverUrl}
                                                alt={playlist.name}
                                                className="absolute inset-0 object-cover"
                                            />
                                        ) : (
                                            <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-primary/50 to-primary/20">
                                                <Music className="h-6 w-6 text-primary" />
                                            </div>
                                        )}
                                    </div>

                                    <div className="min-w-0 flex-1 text-left">
                                        <p className="truncate font-medium text-foreground">
                                            {playlist.name}
                                        </p>
                                        <p className="text-xs text-muted-foreground">
                                            {playlist.tracks.length} tracks
                                        </p>
                                    </div>

                                    <ChevronRight
                                        className={cn(
                                            \'h-5 w-5 text-muted-foreground transition-transform\',
                                            expandedPlaylist === playlist.id &&
                                                \'rotate-90\',
                                        )}
                                    />
                                </button>

                                {/* Expanded track list */}
                                {expandedPlaylist === playlist.id && (
                                    <div className="bg-muted/30">
                                        {playlist.tracks.map((track, index) => (
                                            <button
                                                key={track.id}
