export interface MetricComparisonCardProps extends React.ComponentProps<
    typeof Card
> {
    title: string;
    currentValue: string;
    currentLabel?: string;
    comparisonValue: string;
    comparisonLabel?: string;
    ratio: number; // 0 to 1 (e.g. currentValue / comparisonValue)
    trend?: string;
    trendType?: \'positive\' | \'negative\' | \'neutral\';
}

const MetricComparisonCard = React.forwardRef<HTMLDivElement, MetricComparisonCardProps>(
    (
        {
            className,
            title,
            currentValue,
            currentLabel = \'Current Period\',
            comparisonValue,
            comparisonLabel = \'Previous Period\',
            ratio,
            trend,
            trendType = \'positive\',
            children,
            ...props
        },
        ref,
    ) => {
        const { isHovered, hoverRef } = useHover();

        const combinedRef = React.useCallback(
            (node: HTMLDivElement | null) => {
                hoverRef(node);
                if (typeof ref === \'function\') {
                    ref(node);
                } else if (ref) {
                    (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
                }
            },
            [ref, hoverRef]
        );

        const currentPercentage = Math.min(Math.max(ratio * 100, 0), 100);

        return (
            <Card
                ref={combinedRef}
                className={cn(
                    \'relative overflow-hidden p-6 shadow-md transition-all hover:shadow-lg\',
