                                {item.description && (
                                    <p className="mt-1 max-w-[160px] text-xs leading-relaxed text-muted-foreground">
                                        {item.description}
                                    </p>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
