export type AnimationType =
    | \'radial\'
    | \'wave\'
    | \'random\'
    | \'diagonal\'
    | \'spiral\';

export type AnimationDirection = \'appear\' | \'disappear\';

export interface PixelConfig {
    /** Array of colors for pixels */
    colors: string[];
    /** Gap between pixels in pixels */
    gap: number;
    /** Animation speed (0-100) */
    speed: number;
    /** Minimum pixel size */
    minSize: number;
    /** Maximum pixel size */
    maxSize: number;
    /** Shimmer intensity (0-1) */
    shimmerIntensity: number;
    /** Shape of pixels */
    shape: PixelShape;
    /** Animation pattern type */
    animationType: AnimationType;
    /** Whether to disable focus events */
    noFocus: boolean;
}

export interface PixelState {
    x: number;
    y: number;
    color: string;
    size: number;
    maxSize: number;
    minSize: number;
    speed: number;
    delay: number;
    sizeStep: number;
    counter: number;
    counterStep: number;
    isIdle: boolean;
    isReverse: boolean;
    isShimmer: boolean;
}

